function extractPublicEmails(html){const values=[];const source=String(html||"");for(const match of source.matchAll(/\bhref\s*=\s*(?:\"mailto:([^\"]*)\"|'mailto:([^']*)'|mailto:([^\s>]+))/gi))values.push(match[1]??match[2]??match[3]??"");values.push(...extractCloudflareEmails(source));const text=htmlToPublicText(source);values.push(...(text.match(/[A-Z0-9._%+-]+\s*@\s*[A-Z0-9.-]+\s*\.\s*[A-Z]{2,}/gi)||[]));for(const match of text.matchAll(/([A-Z0-9][A-Z0-9._%+-]{0,63})\s*(?:\[|\()?\s*at\s*(?:\]|\))?\s*([A-Z0-9-]+(?:\s*(?:\[|\()?\s*dot\s*(?:\]|\))?\s*[A-Z0-9-]+)+)/gi))values.push(`${match[1]}@${match[2].replace(/\s*(?:\[|\()?\s*dot\s*(?:\]|\))?\s*/gi,".")}`);return [...new Set(values.map(publicEmailValue).filter(Boolean))];}
