function historicalIdentityMatch(p,row){const domain=Boolean(p.domain)&&p.domain===clean(row.domain,200).toLowerCase();const name=identityText(p.business_name)===identityText(row.business_name);const address=Boolean(identityText(p.location))&&identityText(p.location)===identityText(row.location);return (domain&&address)||(name&&address)||(domain&&name&&(!identityText(p.location)||!identityText(row.location)));}
