  if(existing){p={...p,id:existing.id,dedupe_key:existing.dedupe_key,email:p.email||existing.email||"",website:p.website||existing.website||"",website_verified:p.website_verified||Boolean(existing.website_verified),contact_page_url:p.contact_page_url||existing.contact_page_url||"",subscriber_type:existing.subscriber_type||p.subscriber_type,subscriber_type_evidence:existing.subscriber_type_evidence||p.subscriber_type_evidence||"",lia_basis_recorded:Boolean(existing.lia_basis_recorded),lia_status:existing.lia_status||p.lia_status||"not_recorded",consent_recorded:Boolean(existing.consent_recorded),consent_evidence:existing.consent_evidence||p.consent_evidence||"",soft_opt_in_recorded:Boolean(existing.soft_opt_in_recorded),soft_opt_in_evidence:existing.soft_opt_in_evidence||p.soft_opt_in_evidence||"",last_contacted_at:existing.last_contacted_at||null};await db.prepare("UPDATE prospects SET business_name=?,business_type=?,location=?,domain=?,email=CASE WHEN ?<>'' THEN ? ELSE email END,website=CASE WHEN ?<>'' THEN ? ELSE website END,website_verified=CASE WHEN ?=1 THEN 1 ELSE website_verified END,contact_page_url=CASE WHEN ?<>'' THEN ? ELSE contact_page_url END,google_place_id=COALESCE(?,google_place_id),source=?,source_url=?,source_date=?,updated_at=? WHERE id=?").bind(p.business_name,p.business_type,p.location,p.domain,p.email,p.email,p.website,p.website,p.website_verified?1:0,p.contact_page_url,p.contact_page_url,p.google_place_id,p.source,p.source_url,p.source_date,now,p.id).run();}
