function completedLia(p){return p.lia_status==="passed"&&Boolean(p.lia_basis_recorded);}
function complianceFor(p){if(!p.email)return "missing_public_email";const pecr=pecrDecision(p);if(pecr==="unknown_treated_as_individual"||pecr==="individual_consent_required")return "pecr_consent_required";if(pecr==="individual_consent_valid")return "eligible";if(p.lia_status==="failed")return "lia_failed";return completedLia(p)?"eligible":"lia_required";}
const STOP_WORDS=new Set(["with","from","that","this","your","their","business","public","listing","company","limited","active","product","products"]);
function words(value){return String(value||"").toLowerCase().split(/[^a-z0-9]+/).filter(word=>word.length>2&&!STOP_WORDS.has(word));}
function includesTerm(text,term){return term.includes(" ")?text.includes(term):new RegExp(`\\b${term.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}\\b`,"i").test(text);}
function categoryTargetingProfile(value){const type=clean(value,100).toLowerCase();return CATEGORY_TARGETING_PROFILES[type]||CATEGORY_TARGETING_PROFILES[normaliseBusinessType(type,[]) ]||null;}
function bingoOfferFor(profile){return BINGO_OFFERS[profile?.offer]||BINGO_OFFERS.BINGO_SHOP;}
function publicInterestSignals(prospect){return (Array.isArray(prospect?.public_interest_signals)?prospect.public_interest_signals:[]).map(item=>({signal:clean(item?.signal,240),source_url:publicWebsiteUrl(item?.source_url)})).filter(item=>item.signal&&item.source_url).slice(0,3);}
function bestMatch(p,products,min){const profile=categoryTargetingProfile(p.business_type);if(!profile)return null;const signals=publicInterestSignals(p);const evidenceText=`${p.business_name} ${p.business_type} ${p.website||p.domain} ${p.evidence} ${p.location} ${signals.map(signal=>signal.signal).join(" ")}`.toLowerCase();const evidenceWords=new Set(words(evidenceText));const offer=bingoOfferFor(profile);let best=null;for(const product of products){const productText=`${product.name} ${product.category} ${product.description} ${product.tags}`.toLowerCase();const affinityHits=profile.productTerms.filter(term=>includesTerm(productText,term));if(!affinityHits.length)continue;const overlap=[...new Set(words(productText).filter(word=>evidenceWords.has(word)))];const breakdown={category_match:30,service_match:Math.min(20,signals.length*8),product_match:20+Math.min(20,affinityHits.length*5),location_match:p.location?5:0,evidence_quality:p.evidence?5:0,offer_relevance:10};let score=Object.values(breakdown).reduce((total,value)=>total+value,0)+Math.min(10,overlap.length*2);score=Math.min(100,score);if(score<min||best&&score<=best.score)continue;const reasons=[`${profile.label} category`,...signals.map(signal=>signal.signal),`${offer.label} is relevant`,`catalogue terms: ${affinityHits.slice(0,3).join(", ")}`];best={product,score,score_breakdown:breakdown,matched_bingo_offer:offer,public_interest_signals:signals,reason:`${profile.label} relevance: ${reasons.join("; ")}.`};}return best;}
function normaliseProducts(items,env={}){return (Array.isArray(items)?items:[]).map(p=>{const source=clean(p.source||p.supplier||"catalogue",60).toLowerCase();const availability=clean(p.availability||p.stockStatus||p.status,60).toLowerCase();const numericStock=Number(p.stock??p.quantity);const enabledSource=p.sourceEnabled!==false&&p.enabled!==false&&!(source==="etsy"&&(!enabled(env.ETSY_FEATURE_ENABLED)||!enabled(env.ETSY_SYNC_ENABLED)));const available=p.available!==false&&!/removed|deleted|unavailable|out of stock|sold out|disabled|hidden/.test(availability)&&(!Number.isFinite(numericStock)||numericStock>0);return {id:clean(p.id||p.sku||p.externalListingId,80),name:clean(p.name||p.title||p.display_title,160),category:clean(p.category,100),description:clean(p.description||p.display_description,800),source,tags:clean(Array.isArray(p.tags)?p.tags.join(" "):p.tags||p.keywords,300),price:clean(p.priceLabel||p.price?.display||p.price,80),url:httpsUrl(p.url||p.publicUrl||p.public_url||p.externalUrl||p.listingUrl||p.itemUrl),available,enabledSource};}).filter(p=>p.id&&p.name&&p.url&&p.available&&p.enabledSource);}
async function generateDraft(env,p,match){if(!p.evidence||!match?.reason||!match?.product||!match?.matched_bingo_offer)return null;const profile=categoryTargetingProfile(p.business_type);if(!profile)return null;const contactSource=publicWebsiteUrl(p.contact_name_source_url);const verifiedContact=Boolean(p.contact_name&&contactSource&&p.website&&sameBusinessDomain(new URL(contactSource).hostname,new URL(p.website).hostname));const greeting=verifiedContact?`Hi ${p.contact_name.split(" ")[0]},`:`Hello ${p.business_name} team,`;const signal=match.public_interest_signals?.[0]?.signal||"";const research=signal?`I came across your business and saw that your public website mentions ${signal.replace(/^Public website mentions\s+/i,"")}.`:`I came across your public business listing while researching ${profile.label} businesses.`;const offer=match.matched_bingo_offer;const body=[greeting,"",research,"",`${offer.description} The shop currently includes ${match.product.name}: ${match.product.url}`,`I thought this could be a relevant fit for your ${profile.angle}.`,"","If it is useful, I would be happy to share more information. Reply unsubscribe to opt out.","","Best wishes,","Bingo Dog Wash"].join("\n");return {subject:clean(`${p.business_name}: a relevant Bingo Dog Wash idea`,160),body:clean(body,3000)};}

async function messageAction(env,id,action){const db=env.GIFT_CARD_DB;const row=await db.prepare("SELECT o.*,p.email,p.domain,p.subscriber_type,p.lia_basis_recorded,p.lia_status,p.consent_recorded,p.soft_opt_in_recorded FROM outreach_messages o JOIN prospects p ON p.id=o.prospect_id WHERE o.id=?").bind(id).first();if(!row)return json({ok:false,error:"Message not found."},404);const now=new Date().toISOString();if(action==="reject"){await db.prepare("UPDATE outreach_messages SET status='rejected',updated_at=? WHERE id=?").bind(now,id).run();return json({ok:true,status:"rejected"});}const gate=complianceFor({...row,lia_basis_recorded:Boolean(row.lia_basis_recorded),consent_recorded:Boolean(row.consent_recorded),soft_opt_in_recorded:Boolean(row.soft_opt_in_recorded)});if(action==="approve"){if(gate!=="eligible"||row.compliance_status!=="eligible"||await suppressed(db,row.email,row.domain))return json({ok:false,error:"Compliance or suppression gate prevents approval."},409);await db.prepare("UPDATE outreach_messages SET status='approved',approved_at=?,updated_at=? WHERE id=?").bind(now,now,id).run();return json({ok:true,status:"approved"});}if(!enabled(env.AI_EMAIL_SENDING_ENABLED))return json({ok:false,error:"Email sending is disabled."},409);if(row.status!=="approved")return json({ok:false,error:"Human approval is required before sending."},409);if(row.provider!=="brevo")return json({ok:false,error:"Unexpected outreach provider; expected Brevo."},409);if(!brevoReady(env))return json({ok:false,error:"Approved Brevo campaign sender is not configured."},409);if(await suppressed(db,row.email,row.domain))return json({ok:false,error:"Recipient is suppressed."},409);if(gate!=="eligible")return json({ok:false,error:`Compliance gate: ${gate}.`},409);try{const contactResponse=await fetch("https://api.brevo.com/v3/contacts",{method:"POST",headers:{"api-key":env.BREVO_API_KEY,"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({email:row.email,listIds:[Number(env.BREVO_OUTREACH_LIST_ID)],updateEnabled:true})});if(!contactResponse.ok&&contactResponse.status!==400)throw new Error("contact rejected");const response=await fetch("https://api.brevo.com/v3/smtp/email",{method:"POST",headers:{"api-key":env.BREVO_API_KEY,"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({sender:{email:env.AI_EMAIL_SENDER_EMAIL,name:env.AI_EMAIL_SENDER_NAME},to:[{email:row.email}],templateId:Number(env.BREVO_OUTREACH_TEMPLATE_ID),subject:row.subject,params:{OUTREACH_SUBJECT:row.subject,OUTREACH_BODY_TEXT:row.body_text},tags:["bingo-outreach"]})});if(!response.ok)throw new Error("provider rejected");const result=await response.json();await db.prepare("UPDATE outreach_messages SET status='sent',sent_at=?,provider='brevo',provider_message_id=?,updated_at=? WHERE id=?").bind(now,clean(result?.messageId,200),now,id).run();await db.prepare("UPDATE prospects SET last_contacted_at=?,updated_at=? WHERE id=?").bind(now,now,row.prospect_id).run();return json({ok:true,status:"sent",provider:"brevo"});}catch{await db.prepare("UPDATE outreach_messages SET status='failed',provider='brevo',failure_reason='Provider rejected send',updated_at=? WHERE id=?").bind(now,id).run();return json({ok:false,channel:"email",provider:"brevo",error:"Brevo rejected the send; other distribution channels are unaffected."},502);}}
async function prospectAction(env,id,action,request){
  const db=env.GIFT_CARD_DB;const p=await db.prepare("SELECT email,domain,subscriber_type,subscriber_type_evidence,consent_recorded,soft_opt_in_recorded FROM prospects WHERE id=?").bind(id).first();if(!p)return json({ok:false,error:"Prospect not found."},404);const now=new Date().toISOString();
  if(action==="record-lia"){
    const input=await safeJson(request);const fields=["purpose","necessity","balancing","evidenceSource","subscriberEvidence","reviewerReference"];const result=clean(input.result,20);
    if(input.confirmed!==true||!["passed","failed"].includes(result)||fields.some(field=>clean(input[field],2000).length<5))return json({ok:false,error:"A complete three-part LIA, evidence, reviewer reference and passed/failed result are required."},400);
    const pecr=pecrDecision(p);if(p.subscriber_type==="unknown")return json({ok:false,error:"Subscriber classification is required before an LIA can be completed; unknown is treated as individual for PECR."},409);if(p.subscriber_type!=="corporate"&&pecr!=="individual_soft_opt_in_valid")return json({ok:false,error:"An LIA cannot replace PECR consent or soft opt-in for an individual subscriber."},409);
    if(result==="passed"&&(input.optOutConfirmed!==true||input.suppressionConfirmed!==true))return json({ok:false,error:"A passed LIA requires confirmation of the opt-out safeguard and suppression check."},400);if(result==="passed"&&await suppressed(db,p.email,p.domain))return json({ok:false,error:"A suppressed prospect cannot pass the LIA workflow."},409);
    const passed=result==="passed";await db.prepare("UPDATE prospects SET lia_basis_recorded=?,lia_status=?,lia_purpose_test=?,lia_necessity_test=?,lia_balancing_test=?,lia_assessed_at=?,lia_evidence_source=?,lia_subscriber_type=?,lia_subscriber_evidence=?,lia_reviewer_reference=?,lia_opt_out_confirmed=?,lia_suppression_confirmed=?,compliance_status=CASE WHEN email='' THEN 'missing_public_email' WHEN ?=1 THEN 'eligible' ELSE 'lia_failed' END,updated_at=? WHERE id=?").bind(passed?1:0,result,clean(input.purpose,2000),clean(input.necessity,2000),clean(input.balancing,4000),now,clean(input.evidenceSource,1000),p.subscriber_type,clean(input.subscriberEvidence,2000),clean(input.reviewerReference,200),input.optOutConfirmed===true?1:0,input.suppressionConfirmed===true?1:0,passed?1:0,now,id).run();await db.prepare("INSERT INTO prospect_sources (id,prospect_id,source,source_url,source_date,evidence,created_at) VALUES (?,?,?,?,?,?,?) ON CONFLICT(prospect_id,source,source_url) DO UPDATE SET evidence=excluded.evidence,source_date=excluded.source_date").bind(crypto.randomUUID(),id,"compliance_review","https://bingodogwash.com/admin/ai-drafts.html",now.slice(0,10),`Three-part LIA ${result}; reviewer: ${clean(input.reviewerReference,200)}; evidence: ${clean(input.evidenceSource,1000)}`,now).run();return json({ok:true,status:`lia_${result}`});
  }
  if(action==="block")await db.prepare("UPDATE prospects SET status='blocked',updated_at=? WHERE id=?").bind(now,id).run();else await db.prepare("INSERT INTO suppression_list (id,email,domain,reason,created_at) VALUES (?,?,?,?,?) ON CONFLICT(email,domain) DO UPDATE SET reason=excluded.reason").bind(crypto.randomUUID(),p.email||"",p.domain||"","admin",now).run();return json({ok:true,status:action==="block"?"blocked":"suppressed"});
}
export async function purgeExpiredProspects(db,now=new Date().toISOString()){if(!db)return {purged:0};const eligible="prospect_id IN (SELECT id FROM prospects WHERE retention_expires_at < ? AND converted_at IS NULL AND last_contacted_at IS NULL)";await db.prepare(`DELETE FROM outreach_messages WHERE ${eligible}`).bind(now).run();await db.prepare(`DELETE FROM prospect_product_matches WHERE ${eligible}`).bind(now).run();await db.prepare(`DELETE FROM prospect_sources WHERE ${eligible}`).bind(now).run();const result=await db.prepare("DELETE FROM prospects WHERE retention_expires_at < ? AND converted_at IS NULL AND last_contacted_at IS NULL").bind(now).run();return {purged:Number(result.meta?.changes||0)};}
async function suppressed(db,email,domain){return Boolean(await db.prepare("SELECT 1 AS blocked FROM suppression_list WHERE (email<>'' AND email=?) OR (domain<>'' AND domain=?) LIMIT 1").bind(email,domain).first());}
async function finishRun(db,id,v){const d=v.diagnostics||{};await db.prepare("UPDATE outreach_runs SET status=?,prospects_found=?,prospects_queued=?,blocked_count=?,search_api_cost=?,cost_cap=?,partial=?,raw_results=?,normalized_results=?,rejected_count=?,qualified_count=?,provider_errors=?,google_searches_attempted=?,google_searches_completed=?,google_duplicates_rejected=?,google_invalid_rejected=?,completed_at=? WHERE id=?").bind(v.status,v.found||0,v.queued||0,v.blocked||0,v.cost||0,v.cap||0,v.partial||0,d.googleResults||0,d.candidatesAccepted||0,(d.duplicatesRejected||0)+(d.invalidRejected||0),d.candidatesAccepted||0,JSON.stringify(d.providerErrors||[]),d.searchesAttempted||0,d.searchesCompleted||0,d.duplicatesRejected||0,d.invalidRejected||0,v.now,id).run();return {ok:true,runId:id,status:v.status,prospectsFound:v.found||0,prospectsQueued:v.queued||0,blocked:v.blocked||0,searchApiCost:v.cost||0,costCap:v.cap||0,partial:Boolean(v.partial),diagnostics:d};}
function capability(env){const missing=[];if(!enabled(env.AI_PROSPECTING_ENABLED))missing.push("AI_PROSPECTING_ENABLED=true");if(!env.COMPANIES_HOUSE_API_KEY&&!env.GOOGLE_PLACES_API_KEY)missing.push("COMPANIES_HOUSE_API_KEY or GOOGLE_PLACES_API_KEY");const campaignProviderReady=brevoReady(env);return {prospectingEnabled:enabled(env.AI_PROSPECTING_ENABLED),manualProspectingEnabled:enabled(env.AI_MANUAL_PROSPECTING_ENABLED),sendingEnabled:enabled(env.AI_EMAIL_SENDING_ENABLED)&&campaignProviderReady,campaignProviderReady,campaignProvider:"brevo",ready:missing.length===0,sources:[...SOURCES],missing};}
function manualPreferences(input,env){const categoryInput=input?.categories;const categories=Array.isArray(categoryInput)&&categoryInput.every(value=>typeof value==="string")?[...new Set(categoryInput.map(value=>clean(value,100).toLowerCase()))]:[];if(!categories.length)return {ok:false,error:"Select at least one business category."};if(categories.some(category=>!MANUAL_CATEGORIES.has(category)))return {ok:false,error:"Unsupported business category."};const location=typeof input?.location==="string"?clean(input.location,120):"";if(!location||!/^[\p{L}\p{N} .,'&()\-]+$/u.test(location))return {ok:false,error:"Enter a valid search location."};const budget=input?.budget;const serverCap=positiveNumber(env.AI_PROSPECTING_MAX_COST_GBP,1);if(typeof budget!=="number"||!Number.isFinite(budget)||budget<=0)return {ok:false,error:"Enter a positive search budget."};if(budget>serverCap)return {ok:false,error:`Budget exceeds the server maximum of £${serverCap.toFixed(2)}.`};const maxProspects=input?.maxProspects;if(!Number.isInteger(maxProspects)||![5,10,20].includes(maxProspects))return {ok:false,error:"Maximum businesses must be 5, 10, or 20."};return {ok:true,value:{location,categories,budget,maxProspects:Math.min(maxProspects,Math.min(Math.max(Number(env.AI_PROSPECTING_MAX_PROSPECTS)||20,1),100)),manualGoogle:true}};}
function brevoReady(env){return env.AI_EMAIL_CAMPAIGN_PROVIDER==="brevo"&&Boolean(env.BREVO_API_KEY)&&positiveInteger(env.BREVO_OUTREACH_TEMPLATE_ID)>0&&positiveInteger(env.BREVO_OUTREACH_LIST_ID)>0&&Boolean(emailValue(env.AI_EMAIL_SENDER_EMAIL))&&Boolean(clean(env.AI_EMAIL_SENDER_NAME,100));}
function stableId(value){let h=2166136261;for(const c of value){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return `prospect-${(h>>>0).toString(16)}`;}
function nullablePlaceId(value){const id=clean(value,200);return id||null;}
function companyKey(value){return clean(value,160).toLowerCase().replace(/\b(limited|ltd|llp)\b/g,"").replace(/[^a-z0-9]/g,"");}function isPublicHostname(host){const h=String(host||"").toLowerCase().replace(/^\[|\]$/g,"");if(!h||h==="localhost"||h.endsWith(".localhost")||h.endsWith(".local")||h.endsWith(".internal")||h.endsWith(".lan")||h.endsWith(".home")||h.includes(":"))return false;if(/^\d+\.\d+\.\d+\.\d+$/.test(h))return false;return !/^(?:0|127|10)\.|^169\.254\.|^192\.168\.|^172\.(?:1[6-9]|2\d|3[01])\./.test(h);}
function positiveNumber(v,f){const n=Number(v);return Number.isFinite(n)&&n>=0?n:f;}function boundedInteger(v,f,min,max){const n=Number(v);return Number.isSafeInteger(n)&&n>=min&&n<=max?n:f;}function positiveInteger(v){const n=Number(v);return Number.isSafeInteger(n)&&n>0?n:0;}function enabled(v){return /^(1|true|yes|on)$/i.test(String(v||"").trim());}function clean(v,n=500){return String(v||"").replace(/\s+/g," ").trim().slice(0,n);}function emailValue(v){const e=String(v||"").trim().toLowerCase();return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)?e.slice(0,254):"";}function httpsUrl(v){try{const u=new URL(String(v||""));return u.protocol==="https:"?u.toString():"";}catch{return "";}}function domainOf(v){try{return new URL(String(v||"")).hostname.toLowerCase().replace(/^www\./,"");}catch{return "";}}function parseJson(v,f){try{return typeof v==="string"?JSON.parse(v):v||f;}catch{return f;}}function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);}async function safeJson(r){try{return await r.json();}catch{return {};}}async function safeEqual(a,b){const [left,right]=await Promise.all([digest(a),digest(b)]);if(left.length!==right.length)return false;let x=0;for(let i=0;i<left.length;i+=1)x|=left[i]^right[i];return x===0;}async function isAdmin(r,e){const expected=String(e.ADMIN_API_TOKEN||"");const supplied=(r.headers.get("Authorization")||"").match(/^Bearer\s+(.+)$/i)?.[1]||r.headers.get("X-Admin-Token")||"";if(!expected||!supplied)return false;return safeEqual(expected,supplied);}async function digest(v){return new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(v)));}function json(body,status=200){return new Response(JSON.stringify(body),{status,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"}});}

